BEGIN
PERFORM pg_advisory_xact_lock(hashtext('sam-import-14257'));
-- Shared keyref is not a property identifier.
IF EXISTS (SELECT 1 FROM listing_sources WHERE upper(reference_code)='1P0017' OR source_url ~ '[?&]id=14257(&|$)') OR EXISTS (SELECT 1 FROM listings WHERE public_listing_id='1626e0d6-40b1-4127-a96f-1e420638e729' OR slug='sam-direct-sale-shophouse-land-laem-thong-si-racha-1p0017' OR description ILIKE '%1P0017%' OR (abs(latitude-13.091330505220354)<0.0001 AND abs(longitude-100.9283292588632)<0.0001 AND abs(land_area_sqm-3924)<1)) THEN RAISE NOTICE 'SAM 1P0017 exists; skipping'; RETURN; END IF;
SELECT id INTO admin_user_id FROM auth_users WHERE lower(email)='mapxprop@gmail.com' AND deleted_at IS NULL ORDER BY id LIMIT 1;
