INSERT INTO public.listing_transaction_terms (listing_id, term_code, label_th, label_en, value_th, value_en, payer_code, sort_order) VALUES (property_listing_id, 'transfer_inventory', 'ทะเบียนอาคารและสิ่งปลูกสร้างอื่น', 'Registered building and other structures', 'ทะเบียนระบุ 3 ชั้น สำรวจพบชั้นลอยเพิ่ม สิ่งปลูกสร้างอื่นยังไม่ยืนยันว่าเป็นส่วนควบ โอนตามทะเบียนที่ SAM รับโอนเท่านั้น', 'Three storeys registered; mezzanine surveyed. Other structures are not confirmed as part of the land. Transfer follows registered acquisition only', 'unspecified', 20) ;
INSERT INTO public.listing_transaction_terms (listing_id, term_code, label_th, label_en, value_th, value_en, payer_code, sort_order) VALUES (property_listing_id, 'frontage_sections', 'ส่วนติดถนนประมาณ 5 ม. และ 4 ม.', 'Approx. 5 m and 4 m frontage sections', 'ด้านใต้ยาวรวมประมาณ 98.5 ม. ไม่ได้ติดถนนตลอดแนว ตรวจสิทธิทางและผังแปลง', 'The 98.5 m southern side is not continuous road frontage; confirm access rights and the plot plan', 'unspecified', 30) ;
INSERT INTO public.listing_transaction_terms (listing_id, term_code, label_th, label_en, value_th, value_en, payer_code, sort_order) VALUES (property_listing_id, 'current_inspection', 'สภาพและภาพต้นทาง', 'Condition and source photographs', 'ภาพภายนอก 5 มี.ค. 2564 ภายใน 13 ม.ค. 2567 ต้องตรวจสภาพและผู้ครอบครองปัจจุบัน', 'Exterior photos: 5 March 2021; interior: 13 January 2024. Verify current condition and occupancy', 'unspecified', 40) ;
