INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=14257&keyref=6007623', '1P0017', now(), 'Official source captured 2026-09-11. Five plots totaling 981 sq.wah; THB 16,652,000 direct purchase. Approximately 98.5 m south side has only 5 m and 4 m road-fronting sections. Registered three-storey shophouse, surveyed mezzanine, unconfirmed legal inclusion of other structures and registered-only transfer disclosed. Exterior photos display 2021-03-05; interiors 2024-01-13. 17 source image URLs yield 16 unique images; 20230731144519_P1.jpg and 1P0017P4_64.jpg have identical SHA256 469ba0477118b0d293cc6d9d9b815682c514b705a7ba5afb3065523b1f97ce08, retained once. No retouching or added watermark. All-status duplicate search found no matches for reference/page/deeds/address/area/nearby coordinates.') ;
INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', 'SAM Direct Sale: 3-Storey Shophouse with Mezzanine and 981 Sq.Wah Land, Si Racha', 'Shophouse at 138/18, Laem Thong Road, Thung Sukhla, Si Racha, Chon Buri, with five adjoining land plots. Total area 2 rai 1 ngan 81 sq.wah, equivalent to 981 sq.wah or 3,924 sq.m. Deeds 37238, 48959, 48960, 48961 and 48962. SAM announced price THB 16,652,000; asset 1P0017.
